import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Vector2 } = ctx.THREE;
  const group = new Group();

  // --- Backdrop plane: we do NOT create a full stage backdrop here (hub handles that).
  // Instead, we create the card plane with the texture.

  // Texture loading
  const material = new MeshBasicNodeMaterial({
    color: '#0b0b10', // fallback surface color
    transparent: true,
  });
  let texture = null; // keep reference for cleanup

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Plane geometry using aspect from atlas region (512x320)
  const aspect = 512 / 320; // 1.6
  const planeWidth = 1.6;
  const planeHeight = planeWidth / aspect; // 1.0
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const mesh = new Mesh(geometry, material);
  mesh.position.z = 0; // front of group
  group.add(mesh);

  // --- Text "Collection 3" ---
  const text = ctx.fontAtlas.createText('Collection 3', {
    fontSize: 39,
    color: '#e8ecf2', // paper
    align: 'center',
    maxWidthPx: 200, // constrain to card width
    letterSpacingPx: 0.5,
  });
  // Position text on the card, slightly below center
  text.position.set(0, -0.2, 0.01); // slight z offset to avoid z-fighting
  text.scale.set(0.002, 0.002, 0.002); // scale to fit scene (fontAtlas creates large meshes)
  group.add(text);

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    material.dispose();
    geometry.dispose();
    if (texture) texture.dispose();
    // no GSAP timelines to kill
  };

  return group;
}
